<?php
require_once __DIR__ . '/_friend_helpers.php';
try { if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $d=friends_input(); $c=friends_connection(); if(!SessionHelper::isAuthenticated()){ApiResponse::unauthorized();exit;} if(!friends_require_active($c)){ApiResponse::forbidden('Active account required.');exit;} if(!friends_csrf($d)){ApiResponse::forbidden('Invalid CSRF token.');exit;} $uid=SessionHelper::getUserId(); $rid=(int)($d['request_id']??0); $action=$d['action']??''; if(!in_array($action,['accept','reject'],true)){ApiResponse::validation(['action'=>'Invalid action.']);exit;} $s=$c->prepare("SELECT * FROM friend_requests WHERE id=:id AND receiver_id=:uid AND status='pending' LIMIT 1");$s->execute(['id'=>$rid,'uid'=>$uid]);$req=$s->fetch(PDO::FETCH_ASSOC); if(!$req){ApiResponse::notFound('Request not found.');exit;} if($action==='accept'){ $c->beginTransaction(); $u=$c->prepare("UPDATE friend_requests SET status='accepted', responded_at=NOW() WHERE id=:id");$u->execute(['id'=>$rid]); $ins=$c->prepare("INSERT INTO friendships (user_id,friend_id,status) VALUES (:a,:b,'accepted') ON DUPLICATE KEY UPDATE status='accepted'"); $ins->execute(['a'=>$req['sender_id'],'b'=>$req['receiver_id']]); $ins->execute(['a'=>$req['receiver_id'],'b'=>$req['sender_id']]); $c->commit(); ApiResponse::success([],'Friend request accepted.'); } else { $u=$c->prepare("UPDATE friend_requests SET status='rejected', responded_at=NOW() WHERE id=:id");$u->execute(['id'=>$rid]); ApiResponse::success([],'Friend request rejected.'); } } catch(Throwable $e){ if(isset($c)&&$c->inTransaction())$c->rollBack(); Logger::error('Friend respond failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to respond.');}
?>
